export const VERSION='1.1.0';
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const money=(v)=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(Number.isFinite(v)?v:0);
export const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
export function dayShift(day,n){return new Date(Date.parse(day+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);}
export function daysBetween(a,b){return Math.round((Date.parse(a+'T12:00:00Z')-Date.parse(b+'T12:00:00Z'))/86400000);}
export function salesFor(data,id,days=7){return data.sales.filter(x=>(!id||x.productId===id)&&daysBetween(data.asOf,x.date)>=0&&daysBetween(data.asOf,x.date)<days);}
export function metrics(data,id,days=7){const rows=salesFor(data,id,days);const units=rows.reduce((a,x)=>a+x.units,0),views=rows.reduce((a,x)=>a+x.views,0),revenue=rows.reduce((a,x)=>a+x.revenue,0);const product=data.products.find(p=>p.id===id);return{units,views,revenue,rate:units/days,conversion:views?units/views:0,margin:rows.reduce((a,x)=>a+x.revenue-x.units*(data.products.find(p=>p.id===x.productId)?.cost||0),0),daysCover:product?(units?product.stock/(units/days):Infinity):0};}
export function demo(scenario='balanced',asOf=today()){
 const products=[
 {id:'cheese',name:'Сыр мягкий, 250 г',category:'Молочная продукция',unit:'шт',price:390,cost:230,stock:26,expiresIn:2,leadDays:2,photos:3,completeness:94,color:'peach',symbol:'С'},
 {id:'milk',name:'Молоко фермерское, 1 л',category:'Молочная продукция',unit:'бут',price:140,cost:75,stock:8,expiresIn:5,leadDays:3,photos:3,completeness:92,color:'blue',symbol:'М'},
 {id:'honey',name:'Мёд цветочный, 500 г',category:'Пасека',unit:'бан',price:650,cost:340,stock:48,expiresIn:180,leadDays:7,photos:1,completeness:48,color:'honey',symbol:'М'},
 {id:'eggs',name:'Яйца деревенские, 10 шт',category:'Птицеводство',unit:'уп',price:190,cost:115,stock:82,expiresIn:14,leadDays:2,photos:3,completeness:92,color:'sage',symbol:'Я'},
 {id:'curd',name:'Творог 9%, 400 г',category:'Молочная продукция',unit:'шт',price:280,cost:170,stock:35,expiresIn:5,leadDays:2,photos:2,completeness:78,color:'blue',symbol:'Т'},
 {id:'jam',name:'Варенье из малины, 300 г',category:'Заготовки',unit:'бан',price:420,cost:210,stock:64,expiresIn:240,leadDays:10,photos:2,completeness:82,color:'berry',symbol:'В'},
 {id:'potato',name:'Картофель мытый, 2 кг',category:'Овощи',unit:'уп',price:160,cost:90,stock:90,expiresIn:25,leadDays:3,photos:3,completeness:88,color:'peach',symbol:'К'},
 {id:'tea',name:'Иван-чай, 70 г',category:'Травы и напитки',unit:'уп',price:350,cost:140,stock:53,expiresIn:300,leadDays:7,photos:1,completeness:65,color:'sage',symbol:'Ч'}];
 const rates=[2,7,0.55,5,3,0.8,4,0.5],sales=[];
 for(let day=27;day>=0;day--)products.forEach((p,j)=>{const wave=1+0.22*Math.sin(day*1.8+j)+((27-day)%7===5?.2:0);const units=Math.max(0,Math.round(rates[j]*wave));sales.push({productId:p.id,date:dayShift(asOf,-day),units,views:Math.round((j===2?95:j===7?48:rates[j]*22)*wave),revenue:units*p.price});});
 if(scenario==='harvest'){products[0].stock=60;products[4].stock=75;products[4].expiresIn=2;products[1].stock=35;}
 if(scenario==='quiet'){products[0].stock=6;products[0].expiresIn=5;products[1].stock=55;products[2].completeness=92;products[2].photos=3;}
 return{schemaVersion:1,asOf,farm:'Сосновый берег',demo:true,scenario,products,sales,segments:[{id:'repeat',name:'Давно не заказывали',count:64,consented:38,avgCheck:1250,marginRate:0.36,lastOrderDays:32},{id:'regular',name:'Постоянные покупатели',count:92,consented:67,avgCheck:1680,marginRate:0.34,lastOrderDays:6},{id:'new',name:'Первая покупка',count:47,consented:31,avgCheck:890,marginRate:0.32,lastOrderDays:12}],updatedAt:asOf,source:'Учебный набор, 28 дней'};
}
export function quality(data){const issues=[];if(daysBetween(today(),data.updatedAt)>2)issues.push('Данные старше двух дней: обновите остатки перед решением.');for(const p of data.products){if(!data.sales.some(s=>s.productId===p.id))issues.push(p.name+': нет истории продаж.');if(p.expiresIn===0&&p.stock>0)issues.push(p.name+': проверьте точный срок партии до предложения продажи.');if(p.cost===0)issues.push(p.name+': проверьте нулевую себестоимость.');if(p.price<=p.cost)issues.push(p.name+': цена не выше себестоимости.');}if(!data.segments.length)issues.push('Клиентские сегменты не загружены.');return{score:clamp(100-issues.length*10,0,100),issues};}
export function rankScore(a,goal='balanced'){const impact=clamp(Math.log1p(a.low)/Math.log(10001),0,1);const ease=clamp(1-a.effort/60,0,1);let score=100*(.45*impact+.30*a.urgency+.15*a.reliability+.10*ease);if(goal==='waste'&&a.type==='waste')score+=10;if(goal==='growth'&&['card','retention','bundle'].includes(a.type))score+=8;return Math.round(clamp(score,0,100));}
export function candidates(data,options={}){
 const arr=[],q=quality(data),fresh=daysBetween(today(),data.updatedAt)<=2;
 const add=(a)=>{a.reliability=Math.min(a.reliability,fresh?.95:.35);a.id=a.type+'-'+(a.productId||a.segmentId||'farm');a.score=rankScore(a,options.goal);a.status='new';arr.push(a);};
 for(const p of data.products){const m=metrics(data,p.id),unitMargin=p.price-p.cost;if(!Number.isFinite(m.rate)||m.rate<=0)continue;
  const risk=Math.max(0,p.stock-m.rate*p.expiresIn);
  if(risk>=3&&p.expiresIn>0&&p.expiresIn<=5&&unitMargin>0){const discount=.15,margin=p.price*(1-discount)-p.cost;const baseLoss=Math.min(p.stock,m.rate*p.expiresIn)*p.price*discount;if(margin>0)add({type:'waste',productId:p.id,title:`Сохранить партию: ${p.name.toLowerCase()}`,short:'Партия до списания',label:'Сохранить маржу',low:Math.max(0,Math.round(risk*.3*margin-baseLoss)),high:Math.max(0,Math.round(risk*.6*margin-baseLoss)),effort:10,urgency:p.expiresIn<=2?1:.8,reliability:.85,reason:`Осталось ${p.stock} ${p.unit}. При текущем темпе за ${p.expiresIn} дн. уйдёт около ${Math.ceil(m.rate*p.expiresIn)}. Под риском ${Math.ceil(risk)} ${p.unit}.`,formula:`Излишек ${risk.toFixed(1)} × доля реализации 30–60% × маржа после скидки ${money(margin)} минус ${money(baseLoss)} потери маржи на ожидаемых обычных продажах. Цена −15%, себестоимость ${money(p.cost)}.`,assumption:'30–60% излишка удастся реализовать. Учтена скидка на ожидаемые обычные продажи, не учтены комиссии и упаковка. Это гипотеза, не результат эксперимента.',horizon:Math.min(5,p.expiresIn),steps:['Пересчитать остаток и проверить срок партии','Подготовить скидку 15% без ухода ниже себестоимости','Сохранить черновик акции для ручного размещения'],effectUnits:'маржи под риском'});}
  if(m.daysCover<p.leadDays&&unitMargin>0){const missing=Math.max(0,m.rate*p.leadDays-p.stock);add({type:'stock',productId:p.id,title:`Пополнить ${p.name.toLowerCase()}`,short:'Товар может закончиться',label:'Не упустить маржу',low:Math.round(missing*.5*unitMargin),high:Math.round(missing*.9*unitMargin),effort:15,urgency:Math.max(.7,1-m.daysCover/(p.leadDays*2)),reliability:.9,reason:`Запаса на ${m.daysCover.toFixed(1)} дн., следующая поставка через ${p.leadDays} дн. Средние продажи: ${m.rate.toFixed(1)} ${p.unit}/день.`,formula:`Недостающий объём ${missing.toFixed(1)} × сохранённый спрос 50–90% × маржа ${money(unitMargin)}. Затраты на ускоренную поставку не учтены.`,assumption:'Спрос останется близким к прошлой неделе. Доступность поставки проверяет фермер.',horizon:p.leadDays,steps:['Проверить фактический остаток','Уточнить ближайшую поставку','Подготовить заявку без автоматической отправки'],effectUnits:'маржи при сохранении спроса'});}
  if(m.views>=100&&(p.completeness<80||p.photos<2)&&unitMargin>0){const upliftLow=.003,upliftHigh=.008;add({type:'card',productId:p.id,title:`Доработать карточку: ${p.name.toLowerCase()}`,short:'Покупатели смотрят, но не покупают',label:'Проверить рост маржи',low:Math.round(m.views*upliftLow*unitMargin),high:Math.round(m.views*upliftHigh*unitMargin),effort:20,urgency:.55,reliability:.65,reason:`За 7 дней ${m.views} просмотров и ${m.units} продаж. Заполненность ${p.completeness}%, фотографий: ${p.photos}.`,formula:`${m.views} просмотров × предполагаемый прирост конверсии 0,3–0,8 п.п. × ${money(unitMargin)} маржи.`,assumption:'Прирост 0,3–0,8 п.п. задан для сценария. Причинность не доказана: нужен тест на сопоставимом трафике.',horizon:7,steps:['Добавить фактические характеристики и фото масштаба','Проверить цену, фасовку и условия получения','Подготовить новую версию и измерить конверсию'],effectUnits:'дополнительной маржи за 7 дней'});}
 }
 for(const s of data.segments){if(s.lastOrderDays>=21&&s.consented>=10){add({type:'retention',segmentId:s.id,title:`Вернуть покупателей без массовой скидки`,short:'Повторные покупки',label:'Проверить возврат клиентов',low:Math.round(s.consented*.03*s.avgCheck*s.marginRate),high:Math.round(s.consented*.08*s.avgCheck*s.marginRate),effort:15,urgency:.5,reliability:.55,reason:`${s.count} покупателей не заказывали ${s.lastOrderDays} дня. Согласие на сообщения есть у ${s.consented}.`,formula:`${s.consented} адресатов с согласием × предполагаемый отклик 3–8% × средний чек ${money(s.avgCheck)} × валовая маржа ${Math.round(s.marginRate*100)}%. Стоимость канала не учтена.`,assumption:'Отклик 3–8% условный. Рассылка только после проверки согласий и подключения канала, которого в MVP нет.',horizon:7,steps:['Проверить сегмент и согласия в своей CRM','Подготовить короткое сообщение без скидки','Сохранить черновик. Отправить самостоятельно в своей CRM'],effectUnits:'валовой маржи при отклике'});}}
 if(q.issues.length)add({type:'data',title:'Проверить исходные данные',short:'Надёжность расчётов',label:'Уточнить перед действием',low:0,high:0,effort:5,urgency:1,reliability:1,reason:q.issues[0],formula:'Денежный эффект не рассчитывается: сначала нужны корректные данные.',assumption:'Без надёжных остатков и себестоимости рекомендации требуют ручной проверки.',horizon:1,steps:['Открыть источник','Уточнить остатки и себестоимость','Импортировать свежие данные'],effectUnits:'качество данных'});
 return arr.sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id));
}
export function recommendations(data,state={},limit=3){const day=today();return candidates(data,{goal:state.goal}).filter(a=>!state.events?.some(e=>e.actionId===a.id&&e.day===day&&['approved','done','rejected'].includes(e.status))&&!state.events?.some(e=>e.actionId===a.id&&e.status==='snoozed'&&e.until>=day)).slice(0,limit);}
export function campaign(product,discount=15,quantity=10){const d=clamp(Number(discount)||0,0,70)/100;const q=clamp(Math.floor(Number(quantity)||0),0,product.stock);const price=Math.round(product.price*(1-d));return{price,quantity:q,unitMargin:price-product.cost,margin:(price-product.cost)*q,lostMargin:(product.price-price)*q,valid:q>0&&price>product.cost&&product.expiresIn>0&&Number.isFinite(Number(discount))&&Number(discount)>=0&&Number(discount)<=70};}
export function approve(state,action,{confirmed=false,day,parameters={}}={}){if(!confirmed)throw Error('Нужно явное подтверждение фермера.');if(state.events.some(e=>e.actionId===action.id&&e.day===day&&['approved','done'].includes(e.status)))throw Error('Это действие уже подтверждено.');return{...state,events:[{id:'evt-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),actionId:action.id,title:action.title,type:action.type,status:'approved',day,at:new Date().toISOString(),low:action.low,high:action.high,parameters,modelVersion:VERSION,source:'browser-local',externalExecuted:false},...state.events]};}
export function validateDataset(raw){if(!raw||typeof raw!=='object'||raw.schemaVersion!==1)throw Error('Нужен файл формата Росток schemaVersion: 1.');if(!/^\d{4}-\d{2}-\d{2}$/.test(raw.asOf)||!Number.isFinite(Date.parse(raw.asOf)))throw Error('Неверная дата asOf.');if(raw.asOf>today())throw Error('Дата набора не может быть в будущем.');if(!Array.isArray(raw.products)||raw.products.length<1||raw.products.length>500)throw Error('Нужно от 1 до 500 товаров.');if(!Array.isArray(raw.sales)||raw.sales.length>20000)throw Error('Допустимо до 20 000 строк продаж.');if(!Array.isArray(raw.segments)||raw.segments.length>100)throw Error('Допустимо до 100 агрегированных сегментов.');const validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;if(!validDate(raw.asOf))throw Error('Некорректная календарная дата.');const ids=new Set();const num=(v,k,min,max)=>{if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max)throw Error('Неверное числовое поле '+k);return v;};const str=(v,k,max=120)=>{if(typeof v!=='string'||!v.trim()||v.length>max)throw Error('Неверное поле '+k);return v.trim();};const products=raw.products.map(p=>{const id=str(p.id,'id',40);if(!/^[a-zA-Z0-9_-]+$/.test(id)||ids.has(id))throw Error('ID товаров должны быть уникальными латинскими кодами.');ids.add(id);return{id,name:str(p.name,'name'),category:str(p.category,'category'),unit:str(p.unit,'unit',12),price:num(p.price,'price',.01,1e7),cost:num(p.cost,'cost',0,1e7),stock:num(p.stock,'stock',0,1e7),expiresIn:num(p.expiresIn,'expiresIn',0,3650),leadDays:num(p.leadDays,'leadDays',0,365),photos:num(p.photos,'photos',0,100),completeness:num(p.completeness,'completeness',0,100),color:['sage','honey','blue','peach','berry'].includes(p.color)?p.color:'sage',symbol:p.name.slice(0,1)};});const saleKeys=new Set();const sales=raw.sales.map(s=>{const key=s.productId+'|'+s.date;if(saleKeys.has(key))throw Error('Повторная строка товара за одну дату. Агрегируйте продажи по дням.');saleKeys.add(key);if(!ids.has(s.productId))throw Error('Продажа ссылается на неизвестный товар.');if(!validDate(s.date)||s.date>raw.asOf)throw Error('Неверная дата продажи.');return{productId:s.productId,date:s.date,units:num(s.units,'units',0,1e7),views:num(s.views,'views',0,1e9),revenue:num(s.revenue,'revenue',0,1e10)};});const segmentIds=new Set();const segments=raw.segments.map(s=>{const id=str(s.id,'segment id',40);if(segmentIds.has(id))throw Error('ID сегментов повторяются.');segmentIds.add(id);if(s.consented>s.count)throw Error('Согласий не может быть больше участников.');return{id,name:str(s.name,'segment name'),count:num(s.count,'count',0,1e7),consented:num(s.consented,'consented',0,1e7),avgCheck:num(s.avgCheck,'avgCheck',0,1e7),marginRate:num(s.marginRate,'marginRate',0,1),lastOrderDays:num(s.lastOrderDays,'lastOrderDays',0,3650)};});return{schemaVersion:1,asOf:raw.asOf,farm:str(raw.farm||'Моя ферма','farm'),products,sales,segments,demo:raw.demo===true,updatedAt:raw.asOf,source:raw.demo?'Учебный набор':'Импорт JSON, локально'};}
export function productCSV(data){const heads=['id','name','category','unit','price','cost','stock','expiresIn','leadDays','photos','completeness'];return'\uFEFF'+[heads,...data.products.map(p=>heads.map(k=>p[k]))].map(r=>r.map(v=>'"'+String(typeof v==='string'&&/^[=+@\-\t\r]/.test(v)?"'"+v:v).replace(/"/g,'""')+'"').join(';')).join('\r\n');}
export function parseProductCSV(text,data){if(text.length>2e6)throw Error('CSV больше 2 МБ.');const rows=[];let row=[],field='',quoted=false;const input=text.replace(/^\uFEFF/,'');for(let i=0;i<input.length;i++){const c=input[i];if(c==='"'){if(quoted&&input[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===';'&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&input[i+1]==='\n')i++;row.push(field);if(row.some(x=>x!==''))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('Незакрытая кавычка CSV.');if(field||row.length){row.push(field);rows.push(row);}const header=rows.shift()||[];const required=['id','name','category','unit','price','cost','stock','expiresIn','leadDays','photos','completeness'];if(header.join('|')!==required.join('|'))throw Error('Колонки CSV отличаются от шаблона. Скачайте шаблон.');const products=rows.map(r=>{if(r.length!==required.length)throw Error('Неверное число колонок.');return Object.fromEntries(required.map((k,j)=>[k,j>=4?Number(r[j]):r[j]]));});const ids=new Set(products.map(p=>p.id));return validateDataset({...data,products,sales:data.sales.filter(s=>ids.has(s.productId)),demo:false,asOf:data.asOf});}
